def blank(width, height, color=Qt.GlobalColor.white):
    image = QImage(width, height, QImage.Format.Format_ARGB32)
    image.fill(color)
    return image


def fill_region(image, point, color):
    """Exact-color, contiguous scanline flood fill on a detached ARGB32 image."""
    x, y = point.x(), point.y()
    if not image.rect().contains(point):
        return False
    target, replacement = image.pixel(x, y), QColor(color).rgba()
    if target == replacement:
        return False
    pixels = memoryview(image.bits()).cast('I')
    stride, w, h = image.bytesPerLine() // 4, image.width(), image.height()
    stack = [(x, y)]
    while stack:
        x, y = stack.pop()
        if pixels[y * stride + x] != target:
            continue
        left = x
        while left > 0 and pixels[y * stride + left - 1] == target:
            left -= 1
        right = x
        while right + 1 < w and pixels[y * stride + right + 1] == target:
            right += 1
        for col in range(left, right + 1):
            pixels[y * stride + col] = replacement
        for row in (y - 1, y + 1):
            if not 0 <= row < h:
                continue
            in_run = False
            for col in range(left, right + 1):
                matches = pixels[row * stride + col] == target
                if matches and not in_run:
                    stack.append((col, row))
                in_run = matches
    return True


