HOME_RIBBON_REFERENCE = ""
_HOME_RIBBON_PIXMAP = None
SHAPE_TOOLS = ('line','curve','ellipse','rectangle','rounded','polygon','triangle',
               'righttriangle','diamond','pentagon','hexagon','arrow','arrowleft','arrowup',
               'arrowdown','star4','star','star6','speech','ovalspeech','cloud')


def home_reference():
    global _HOME_RIBBON_PIXMAP
    if _HOME_RIBBON_PIXMAP is None:
        _HOME_RIBBON_PIXMAP=QPixmap()
        _HOME_RIBBON_PIXMAP.loadFromData(base64.b64decode(HOME_RIBBON_REFERENCE))
    return _HOME_RIBBON_PIXMAP


class ReferenceRibbonButton(QToolButton):
    """Live control with the reference's native artwork, lettering and hit region."""
    def __init__(self,parent,rect,name,callback=None,checkable=False,default_checked=False,default_enabled=True):
        super().__init__(parent)
        self.source_rect=QRect(*rect);self.setGeometry(self.source_rect)
        self.setAccessibleName(name);self.setToolTip(name);self.setText(name)
        self.setCheckable(checkable);self.default_checked=default_checked
        self.default_enabled=default_enabled;self.setChecked(default_checked)
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.color=None;self.color_rect=None;self.reference_color=None
        if callback:self.clicked.connect(callback)

    def paintEvent(self,event):
        p=QPainter(self)
        p.drawPixmap(self.rect(),home_reference(),self.source_rect)
        if self.isEnabled()!=self.default_enabled:
            # Preserve the captured glyph positions when changing enabled state.
            if not self.isEnabled():
                p.fillRect(self.rect(),QColor(231,238,247,155))
            else:
                image=home_reference().copy(self.source_rect).toImage()
                # Disabled glyphs in this reference are neutral gray. Recolor them
                # without changing their coverage or the blue ribbon background.
                for y in range(image.height()):
                    for x in range(image.width()):
                        c=image.pixelColor(x,y)
                        if max(c.red(),c.green(),c.blue())-min(c.red(),c.green(),c.blue())<24 and c.red()<202:
                            alpha=min(1,(220-c.red())/95)
                            image.setPixelColor(x,y,QColor(*[round(220+(v-220)*alpha) for v in (38,55,73)]))
                p.drawImage(0,0,image)
        if self.isCheckable() and self.isChecked()!=self.default_checked:
            if self.default_checked:
                image=home_reference().copy(self.source_rect).toImage()
                background=home_reference().toImage()
                for y in range(image.height()):
                    for x in range(image.width()):
                        # Keep the thumbnail and the two color samples intact.
                        keep=self.text()=='Brushes' and 4<=x<46 and 2<=y<44 or self.color_rect is not None and self.color_rect.contains(x,y)
                        c=image.pixelColor(x,y)
                        if not keep and (x<2 or x>=image.width()-2 or y<2 or y>=image.height()-2 or c.red()>175 and c.red()>c.green()+5 and c.green()>c.blue()+8):
                            image.setPixelColor(x,y,background.pixelColor(1250,self.source_rect.y()+y))
                p.drawImage(0,0,image)
            elif self.text()!='Select':
                p.fillRect(self.rect().adjusted(1,1,-1,-1),QColor(255,214,107,65))
                p.setPen(QColor('#d9a33a'));p.drawRect(self.rect().adjusted(0,0,-1,-1))
        if self.color is not None and (self.color!=self.reference_color or self.color.alpha()<255):
            if self.color_rect is not None:
                if self.color.alpha() < 255:
                    p.drawTiledPixmap(self.color_rect, Canvas.checker_pixmap())
                p.fillRect(self.color_rect,self.color)
        if self.isEnabled() and (self.underMouse() or self.isDown()):
            p.fillRect(self.rect().adjusted(1,1,-1,-1),QColor(255,230,161,55 if not self.isDown() else 90))
            p.setPen(QColor('#e9bf62'));p.drawRect(self.rect().adjusted(0,0,-1,-1))
        if self.hasFocus() and self.window().isActiveWindow():
            p.setPen(QPen(QColor('#526781'),1,Qt.PenStyle.DotLine));p.drawRect(self.rect().adjusted(3,3,-4,-4))

    def mousePressEvent(self,event):
        if self.color is not None and event.button()==Qt.MouseButton.RightButton:
            self.window().set_color(self.color,True);event.accept();return
        if self.menu() is not None and self.popupMode()==QToolButton.ToolButtonPopupMode.MenuButtonPopup and event.button()==Qt.MouseButton.LeftButton and event.position().y()>=self.height()-20:
            self.showMenu();event.accept();return
        super().mousePressEvent(event)

    def set_color(self,color):
        self.color=QColor(color);self.update()


class TextRibbonPage(QWidget):
    """Windows 7 Paint Text tab: Clipboard | Font | Background | Colors."""
    FONT_GROUP=(123,304); BACKGROUND_GROUP=(306,425); COLORS_X=427; WIDTH=862

