    def selection_icon(self,kind,checked=False):
        pix=QPixmap(24,24);pix.fill(Qt.GlobalColor.transparent);p=QPainter(pix)
        if checked:
            p.setPen(QColor('#c28a30'));p.setBrush(QColor('#fdd67a'));p.drawRoundedRect(QRectF(0.5,0.5,23,23),2,2)
        dotted=QPen(QColor('#3d4d5e'),1,Qt.PenStyle.DotLine)
        if kind=='rect':
            p.setPen(dotted);p.drawRect(5,6,14,12)
        elif kind=='free':
            p.setRenderHint(QPainter.RenderHint.Antialiasing);p.setPen(dotted)
            path=QPainterPath(QPointF(7,4));path.cubicTo(QPointF(1,6),QPointF(3,20),QPointF(11,20))
            path.cubicTo(QPointF(22,21),QPointF(23,13),QPointF(16,12));path.cubicTo(QPointF(13,11),QPointF(13,3),QPointF(7,4))
            p.drawPath(path)
        elif kind=='all':
            p.setPen(dotted);p.drawRect(3,3,17,17)
            p.setPen(QColor('#3f78b8'));p.setBrush(QColor('#a9cdf2'));p.drawRect(7,7,9,9)
        elif kind=='invert':
            p.setPen(dotted);p.drawRect(2,3,12,10)
            p.setPen(QPen(QColor('#3f78b8'),1.5));p.setRenderHint(QPainter.RenderHint.Antialiasing)
            p.drawLine(15,8,21,8);p.drawLine(19,6,21,8);p.drawLine(19,10,21,8)
            p.drawLine(8,14,8,20);p.drawLine(6,18,8,20);p.drawLine(10,18,8,20)
        elif kind=='delete':
            p.setRenderHint(QPainter.RenderHint.Antialiasing);p.setPen(QPen(QColor('#d0402b'),3,Qt.PenStyle.SolidLine,Qt.PenCapStyle.RoundCap))
            p.drawLine(5,5,19,19);p.drawLine(19,5,5,19)
        p.end();return QIcon(pix)

    def build_select_menu(self,parent):
        menu=QMenu(parent);menu.setStyleSheet('QMenu {icon-size:24px;} QMenu::item {padding:6px 28px 6px 10px;}')
        def header(text):
            label=QLabel(text);label.setStyleSheet('background:#dde3ec;color:#4d5967;font-weight:bold;padding:5px 10px;border-bottom:1px solid #c6cfdb;')
            a=QWidgetAction(menu);a.setDefaultWidget(label);menu.addAction(a)
        header('Selection shapes')
        self.selection_shape_actions={}
        for mode,label in (('rect','&Rectangular selection'),('free','&Free-form selection')):
            a=menu.addAction(label);a.triggered.connect(lambda checked=False,m=mode:self.set_selection_mode(m))
            self.selection_shape_actions[mode]=a
        header('Selection options')
        menu.addAction(self.actions['select_all']);menu.addAction(self.actions['invert_selection'])
        menu.addAction(self.actions['delete']);menu.addAction(self.actions['transparent_selection'])
        self.actions['select_all'].setIcon(self.selection_icon('all'))
        self.actions['invert_selection'].setIcon(self.selection_icon('invert'))
        self.actions['delete'].setIcon(self.selection_icon('delete'))
        self.update_selection_menu();return menu

    def update_selection_menu(self):
        for mode,a in self.selection_shape_actions.items():
            a.setIcon(self.selection_icon(mode,self.canvas.selection_mode==mode))

    def set_selection_mode(self,mode):
        self.canvas.commit_selection();self.canvas.selection_mode=mode
        self.update_selection_menu();self.set_tool('select')

    def set_transparent_selection(self,on):
        self.canvas.transparent_selection=on;self.canvas.update()

    def invert_selection(self):
        if self.canvas.tool!='select':self.set_tool('select')
        self.canvas.invert_selection();self.update_ribbon_state()

    def paste_from(self):
        filename,_=QFileDialog.getOpenFileName(self,'Paste from','','Images (*.png *.jpg *.jpeg *.bmp *.gif *.tif *.tiff *.webp)')
        if filename:
            reader=QImageReader(filename);reader.setAutoTransform(True);size=reader.size()
            if size.isValid() and size.width()*size.height()>MAX_PIXELS:return
            image=reader.read()
            if not image.isNull() and self.canvas.paste(image):self.set_tool('select',commit=False)

    def update_ribbon_state(self):
        if not hasattr(self,'outline_button'):return
        selection=not self.canvas.selection.isEmpty()
        for key in ('cut','copy','crop'):self.actions[key].setEnabled(selection)
        self.actions['delete'].setEnabled(selection)
        shape=self.canvas.tool in SHAPE_TOOLS or self.canvas.tool=='trapezoid'
        self.outline_button.setEnabled(shape)
        self.fill_button.setEnabled(self.canvas.tool=='bucket' or shape and self.canvas.tool not in ('line','curve'))
        value=self.canvas.bucket_fill if self.canvas.tool=='bucket' else self.canvas.fill
        for a in self.fill_menu.actions():a.setChecked((a.text()=='Solid color')==value)
        self.size_button.setEnabled(self.canvas.tool in ('brush','pencil','eraser') or shape)

    def set_outline_style(self,style):
        self.canvas.outline=style is not None
        if style is not None:self.canvas.outline_style=style
        styles=(None,Qt.PenStyle.SolidLine,Qt.PenStyle.DotLine,Qt.PenStyle.DashLine,Qt.PenStyle.DashDotLine)
        for a,v in zip(self.outline_menu.actions(),styles):a.setChecked(v==style)

    def set_fill_style(self,value):
        if self.canvas.tool=='bucket':self.canvas.bucket_fill=value
        else:self.canvas.fill=value
        self.update_ribbon_state()

    def set_shape_option(self,attribute,value,menu):
        setattr(self.canvas,attribute,value)
        for action in menu.actions():action.setChecked(action.text().startswith('No ')==(not value))

    def set_width(self,width,menu):
        self.canvas.stroke_width=width
        for action in menu.actions():action.setChecked(action.text()==f'{width} px')
        self.size_button.setToolTip(f'Stroke width: {width} px')

    def select_color_slot(self,slot):
        self.active_color=slot;self.primary_button.setChecked(slot==1);self.secondary_button.setChecked(slot==2)


    def tool_button(self,layout,key,text,*position):
        b=QToolButton();b.setToolTip(text);b.setText(text);b.setIcon(ribbon_icon(key));b.setIconSize(QSize(20,20))
        b.setCheckable(True);b.setFixedSize(26,23);b.clicked.connect(lambda:self.set_tool(key))
        layout.addWidget(b,*position);self.tool_buttons[key]=b;return b


